### 3. `script.js` (JavaScript - A Lógica de Cálculo)

Este script gerencia a lógica, garantindo que, ao inserir dois valores, o terceiro seja calculado corretamente, cobrindo todas as variações da Lei de Ohm e Potência.

```javascript
document.addEventListener('DOMContentLoaded', () => {
    // Inicializa a função de atualização ao carregar, para definir o estado inicial dos outputs
    handleInputChange(); 
});

/**
 * Função principal que é chamada sempre que um campo de input muda.
 * Ela verifica quais campos estão preenchidos e realiza os cálculos necessários.
 */
function handleInputChange() {
    // 1. Captura os valores e converte para números (ou null se vazio)
    const vInput = document.getElementById('inputV');
    const iInput = document.getElementById('inputI');
    const rInput = document.getElementById('inputR');

    // Obtém os valores, tratando campos vazios como 0 ou null para facilitar a lógica
    const V = parseFloat(vInput.value) || null;
    const I = parseFloat(iInput.value) || null;
    const R = parseFloat(rInput.value) || null;

    // 2. Verifica quantos valores foram fornecidos
    const filledCount = [V, I, R].filter(val => val !== null && val !== "").length;

    // 3. Atualiza a interface com base na contagem de preenchimento

    // Caso não haja dados ou menos de 2, limpa os resultados
    if (filledCount < 2) {
        clearResults();
        return;
    }

    // Se houver exatamente 2 valores, calcula o terceiro
    if (filledCount === 2) {
        calculateMissingValue(V, I, R);
    } 
    // Se houver 3 valores, apenas exibe os dados inseridos (e informa que está tudo OK)
    else if (filledCount === 3) {
        displayResults(V, I, R, true);
    }
}

/**
 * Realiza os cálculos com base nos valores fornecidos.
 * @param {number|null} V - Tensão
 * @param {number|null} I - Corrente
 * @param {number|null} R - Resistência
 */
function calculateMissingValue(V, I, R) {
    let calculatedValue = null;
    let missingVariable = '';

    // Lógica de Lei de Ohm: V = R * I

    // 1. Se R está faltando (e V e I estão presentes)
    if (R === null && V !== null && I !== null && I !== 0) {
        calculatedValue = V / I;
        missingVariable = 'R';
    } 
    // 2. Se I está faltando (e V e R estão presentes)
    else if (I === null && V !== null && R !== null && R !== 0) {
        calculatedValue = V / R;
        missingVariable = 'I';
    } 
    // 3. Se V está faltando (e R e I estão presentes)
    else if (V === null && R !== null && I !== null) {
        calculatedValue = R * I;
        missingVariable = 'V';
    }

    // Lógica de Potência: P = V * I (Embora o foco seja Ohm, incluímos a potência)
    // Nota: Para simplificar a UI, focaremos no resultado de Ohm (V, I ou R). 
    // Potência pode ser calculada em qualquer ponto se os 3 valores estivessem presentes ou se tivéssemos um campo P.

    if (calculatedValue !== null) {
        // Atualiza o campo de input correspondente com o resultado
        if (missingVariable === 'R') document.getElementById('inputR').value = calculatedValue.toFixed(3);
        if (missingVariable === 'I') document.getElementById('inputI').value = calculatedValue.toFixed(3);
        if (missingVariable === 'V') document.getElementById('inputV').value = calculatedValue.toFixed(3);

        // Atualiza os outputs com os valores agora completos
        const finalV = parseFloat(document.getElementById('inputV').value);
        const finalI = parseFloat(document.getElementById('inputI').value);
        const finalR = parseFloat(document.getElementById('inputR').value);

        displayResults(finalV, finalI, finalR);
    } else {
        // Isso ocorre se houver inconsistência (ex: R=0 e V/I não faz sentido)
        clearResults();
        // Mantém os valores inseridos, mas avisa que o cálculo não pôde ser feito
    }
}

/**
 * Exibe os valores finais nos painéis de resultado.
 * @param {number|null} v - Tensão
 * @param {number|null} i - Corrente
 * @param {number|null} r - Resistência
 * @param {boolean} allFilled - Indica se todos os campos estavam preenchidos.
 */
function displayResults(v, i, r, allFilled = false) {
    const outputV = document.getElementById('outputV');
    const outputI = document.getElementById('outputI');
    const outputR = document.getElementById('outputR');

    if (allFilled) {
        // Se todos estiverem preenchidos, apenas exibe o que foi digitado
        outputV.innerHTML = `Tensão (V): <strong class="text-primary">${v.toFixed(3)} V</strong>`;
        outputI.innerHTML = `Corrente (A): <strong class="text-warning">${i.toFixed(3)} A</strong>`;
        outputR.innerHTML = `Resistência ($\Omega$): <strong class="text-danger">${r.toFixed(3)} $\Omega$</strong>`;
    } else {
        // Se o cálculo foi feito, exibe o valor encontrado
        outputV.innerHTML = `Tensão (V): <strong class="text-primary">${v !== null ? v.toFixed(3) + ' V' : '---'}</strong>`;
        outputI.innerHTML = `Corrente (A): <strong class="text-warning">${i !== null ? i.toFixed(3) + ' A' : '---'}</strong>`;
        outputR.innerHTML = `Resistência ($\Omega$): <strong class="text-danger">${r !== null ? r.toFixed(3) + ' $\Omega$' : '---'}</strong>`;
    }
}

/**
 * Limpa os textos de saída quando não há dados suficientes.
 */
function clearResults() {
    document.getElementById('outputV').innerHTML = `Tensão (V): Aguardando dados`;
    document.getElementById('outputI').innerHTML = `Corrente (A): Aguardando dados`;
    document.getElementById('outputR').innerHTML = `Resistência ($\Omega$): Aguardando dados`;
}
```

